queen_attack.cpp
```cpp
#include "queen_attack.h"

#include <cstdlib>

namespace queen_attack {

chess_board::chess_board(std::pair<int, int> white, std::pair<int, int> black)
    : white_(white), black_(black) {
    if (white_ == black_) {
        throw std::domain_error("Queens cannot occupy the same position");
    }
    auto valid = [](const std::pair<int, int>& p) {
        return p.first >= 0 && p.first < 8 && p.second >= 0 && p.second < 8;
    };
    if (!valid(white_) || !valid(black_)) {
        throw std::domain_error("Queen position is off the board");
    }
}

std::pair<int, int> chess_board::white() const { return white_; }

std::pair<int, int> chess_board::black() const { return black_; }

bool chess_board::can_attack() const {
    int dx = std::abs(white_.first - black_.first);
    int dy = std::abs(white_.second - black_.second);
    return dx == 0 || dy == 0 || dx == dy;
}

chess_board::operator std::string() const {
    std::string result;
    for (int row = 0; row < 8; ++row) {
        for (int col = 0; col < 8; ++col) {
            std::pair<int, int> pos{row, col};
            if (pos == white_) {
                result += 'W';
            } else if (pos == black_) {
                result += 'B';
            } else {
                result += '_';
            }
            result += (col == 7) ? '\n' : ' ';
        }
    }
    return result;
}

}  // namespace queen_attack
```

