queen_attack.cpp
```cpp
#include "queen_attack.h"

#include <cstdlib>
#include <stdexcept>

namespace queen_attack {

namespace {

constexpr int board_size = 8;

bool is_valid(const position& p) {
    return p.first >= 0 && p.first < board_size && p.second >= 0 &&
           p.second < board_size;
}

}  // namespace

chess_board::chess_board(const position& white, const position& black)
    : white_(white), black_(black) {
    if (!is_valid(white_) || !is_valid(black_)) {
        throw std::domain_error("Queen position must be on the board");
    }
    if (white_ == black_) {
        throw std::domain_error("Queens cannot share the same position");
    }
}

position chess_board::white() const { return white_; }

position chess_board::black() const { return black_; }

bool chess_board::can_attack() const {
    const int row_diff = std::abs(white_.first - black_.first);
    const int col_diff = std::abs(white_.second - black_.second);
    return row_diff == 0 || col_diff == 0 || row_diff == col_diff;
}

chess_board::operator std::string() const {
    std::string result;
    for (int row = 0; row < board_size; ++row) {
        for (int col = 0; col < board_size; ++col) {
            const position current{row, col};
            char c = '_';
            if (current == white_) {
                c = 'W';
            } else if (current == black_) {
                c = 'B';
            }
            result += c;
            if (col < board_size - 1) {
                result += ' ';
            }
        }
        result += '\n';
    }
    return result;
}

}  // namespace queen_attack
```

