        int index = verse - 1;
        StringBuilder sb = new StringBuilder();
        sb.append("This is the ").append(SUBJECTS[index]);
        for (int i = index; i > 0; i--) {
            sb.append("\nthat ").append(ACTIONS[i - 1]).append(" the ").append(SUBJECTS[i - 1]);
        }
        return sb.toString();
    }

