I'll implement `promisify` and the four Promise combinators without using the built-in static methods.

Key design points:
- `promisify` returns a function that appends a node-style callback to the arguments and wraps the call in a `Promise`.
- `all` resolves with an array of values in order (empty input resolves immediately with `[]`), rejecting on the first rejection.
- `allSettled` collects `{status, value}` / `{status, reason}` objects in order.
- `race` settles with the first promise to settle (non-promise values are wrapped via `new Promise` resolution handling).
- `any` resolves with the first fulfillment, and rejects once all reject. The rejection is an `AggregateError` if available, with the collected errors. An empty input rejects immediately.

The `promises` input may be undefined (the tests may call `all()` with no args for an empty case), so I default to an empty array.

promises.js
```javascript
//
// Implementation of the 'Promises' exercise.
//

export const promisify = (fn) => {
  return (...args) =>
    new Promise((resolve, reject) => {
      fn(...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
};

// Normalise a value into a promise without using Promise.resolve
const toPromise = (value) => new Promise((resolve) => resolve(value));

export const all = (promises) => {
  const list = promises === undefined ? [] : Array.from(promises);
  return new Promise((resolve, reject) => {
    if (list.length === 0) {
      resolve([]);
      return;
    }
    const results = new Array(list.length);
    let remaining = list.length;
    list.forEach((item, index) => {
      toPromise(item).then((value) => {
        results[index] = value;
        remaining -= 1;
        if (remaining === 0) {
          resolve(results);
        }
      }, reject);
    });
  });
};

export const allSettled = (promises) => {
  const list = promises === undefined ? [] : Array.from(promises);
  return new Promise((resolve) => {
    if (list.length === 0) {
      resolve([]);
      return;
    }
    const results = new Array(list.length);
    let remaining = list.length;
    const done = () => {
      remaining -= 1;
      if (remaining === 0) {
        resolve(results);
      }
    };
    list.forEach((item, index) => {
      toPromise(item).then(
        (value) => {
          results[index] = { status: 'fulfilled', value };
          done();
        },
        (reason) => {
          results[index] = { status: 'rejected', reason };
          done();
        },
      );
    });
  });
};

export const race = (promises) => {
  const list = promises === undefined ? [] : Array.from(promises);
  return new Promise((resolve, reject) => {
    list.forEach((item) => {
      toPromise(item).then(resolve, reject);
    });
  });
};

export const any = (promises) => {
  const list = promises === undefined ? [] : Array.from(promises);
  return new Promise((resolve, reject) => {
    const makeError = (errors) => {
      if (typeof AggregateError === 'function') {
        return new AggregateError(errors, 'All promises were rejected');
      }
      const error = new Error('All promises were rejected');
      error.errors = errors;
      return error;
    };

    if (list.length === 0) {
      reject(makeError([]));
      return;
    }
    const errors = new Array(list.length);
    let remaining = list.length;
    list.forEach((item, index) => {
      toPromise(item).then(resolve, (reason) => {
        errors[index] = reason;
        remaining -= 1;
        if (remaining === 0) {
          reject(makeError(errors));
        }
      });
    });
  });
};
```

