I implemented `Answer` in `wordy.go` as a small left-to-right parser.

- **Parsing:** The question must start with `What is` and end with `?`. The rest is split into tokens. "multiplied by" and "divided by" are two-word operators, so the parser handles the trailing `by`.
- **Evaluation:** It reads a number first, then repeatedly reads an operator and a number. It applies each operation immediately, which gives left-to-right evaluation.
- **Rejected input:** It returns `(0, false)` for unsupported operations, non-math questions, invalid syntax (such as `1 plus plus 2`), a missing trailing operand, and division by zero.

wordy.go
```go
package wordy

import (
	"strconv"
	"strings"
)

func Answer(question string) (int, bool) {
	q := strings.TrimSpace(question)
	if !strings.HasPrefix(q, "What is") || !strings.HasSuffix(q, "?") {
		return 0, false
	}
	q = strings.TrimSuffix(strings.TrimPrefix(q, "What is"), "?")
	tokens := strings.Fields(q)
	if len(tokens) == 0 {
		return 0, false
	}

	result, err := strconv.Atoi(tokens[0])
	if err != nil {
		return 0, false
	}

	i := 1
	for i < len(tokens) {
		op := tokens[i]
		i++
		switch op {
		case "multiplied", "divided":
			if i >= len(tokens) || tokens[i] != "by" {
				return 0, false
			}
			i++
		case "plus", "minus":
		default:
			return 0, false
		}
		if i >= len(tokens) {
			return 0, false
		}
		n, err := strconv.Atoi(tokens[i])
		if err != nil {
			return 0, false
		}
		i++
		switch op {
		case "plus":
			result += n
		case "minus":
			result -= n
		case "multiplied":
			result *= n
		case "divided":
			if n == 0 {
				return 0, false
			}
			result /= n
		}
	}
	return result, true
}
