// Answer evaluates a simple math word problem such as "What is 5 plus 13?".
//
// The supported operations are "plus", "minus", "multiplied by" and
// "divided by" (integer division). Operations are evaluated strictly from
// left to right, ignoring the usual order of operations, so
// "What is 3 plus 2 multiplied by 3?" is 15.
//
// The boolean result is false if the question cannot be answered: it is not a
// math question, it uses an unsupported operation, its syntax is invalid
// (e.g. "What is 1 plus plus 2?") or it divides by zero.
func Answer(question string) (int, bool) {
	words := strings.Fields(strings.TrimSuffix(strings.TrimSpace(question), "?"))

	// A math question starts with "What is" and has at least one number.
	if len(words) < 3 || words[0] != "What" || words[1] != "is" {
		return 0, false
	}
	words = words[2:]

	// The expression starts with a number...
	result, err := strconv.Atoi(words[0])
	if err != nil {
		return 0, false
	}
	words = words[1:]

	// ...followed by any number of (operator, number) pairs.
	for len(words) > 0 {
		op := words[0]
		words = words[1:]

		// "multiplied" and "divided" must be followed by "by".
		if op == "multiplied" || op == "divided" {
			if len(words) == 0 || words[0] != "by" {
				return 0, false
			}
			words = words[1:]
		}

		// The operator must be followed by a number.
		if len(words) == 0 {
			return 0, false
		}
		operand, err := strconv.Atoi(words[0])
		if err != nil {
			return 0, false
		}
		words = words[1:]

		switch op {
		case "plus":
			result += operand
		case "minus":
			result -= operand
		case "multiplied":
			result *= operand
		case "divided":
			if operand == 0 {
				return 0, false
			}
			result /= operand
		default:
			return 0, false // unsupported operation
		}
	}

	return result, true
}
```

