        throw std::domain_error("Number must be positive");
    }
    long long sum = 0;
    for (long long i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            sum += i;
            long long other = n / i;
            if (other != i) sum += other;
        }
    }
    sum -= n;
    if (sum == n) return classification::perfect;
    if (sum > n) return classification::abundant;
    return classification::deficient;
}

