namespace perfect_numbers {

// The categories of Nicomachus' classification scheme, based on how a number
// compares to its aliquot sum (the sum of its factors excluding itself):
//   perfect   - number == aliquot sum
//   abundant  - number <  aliquot sum
//   deficient - number >  aliquot sum
enum classification { perfect, abundant, deficient };

