#include "perfect_numbers.h"

#include <stdexcept>

namespace perfect_numbers {

namespace {

// Sum of all positive divisors of `number`, excluding `number` itself.
// Divisors come in pairs (d, number / d), so only candidates up to
// sqrt(number) need to be tested. A 64-bit accumulator avoids overflow for
// large inputs.
long long aliquot_sum(int number) {
    if (number == 1) {
        return 0;  // 1 has no divisors other than itself
    }

    long long sum = 1;  // 1 divides every number greater than 1
    for (int divisor = 2; divisor <= number / divisor; ++divisor) {
        if (number % divisor == 0) {
            sum += divisor;
            const int paired = number / divisor;
            if (paired != divisor) {  // don't count a square root twice
                sum += paired;
            }
        }
    }
    return sum;
}

}  // namespace

classification classify(int number) {
    if (number < 1) {
        throw std::domain_error(
            "Classification is only possible for positive integers.");
    }

    const long long sum = aliquot_sum(number);

    if (sum == number) {
        return classification::perfect;
    }
    return sum > number ? classification::abundant : classification::deficient;
}

}  // namespace perfect_numbers
