namespace Bankaccount {
class Bankaccount {
   public:
    void open();
    void close();
    void deposit(int amount);
    void withdraw(int amount);
    int balance();

   private:
    std::mutex mtx_;
    bool open_{false};
    int balance_{0};
};  // class Bankaccount

}  // namespace Bankaccount

#endif  // BANK_ACCOUNT_H
